public static class OrderMetrics
{
    private static readonly Meter Meter = new("MyApp.Orders", "1.0");
    private static readonly Counter<long> OrdersCreated =
        Meter.CreateCounter<long>("orders.created", description: "Orders successfully created");
    private static readonly Histogram<double> CheckoutDuration =
        Meter.CreateHistogram<double>("orders.checkout.duration", unit: "ms");

    public static void RecordCreated() => OrdersCreated.Add(1);

    public static void RecordCheckout(double milliseconds) =>
        CheckoutDuration.Record(milliseconds);
}
